"""Independent source-level vectors and finite-resistance mutation guards."""
from receive_aperture_stimulus import source_profile


def run():
    header = ['time_s', 'REF', 'REF_INPUT', 'SAMPLE_N', 'SAMPLE_INPUT']
    # Hand-written values for the first declared pulse, not generated by the
    # profile evaluator. Inside-node values preserve finite source voltage drop.
    vectors = [(0, 0, 0), (24e-9, 0, 0), (24.2e-9, .6, 1.65),
               (24.4e-9, 1.2, 3.3), (25.5e-9, 1.2, 3.3),
               (25.7e-9, 1.2, 1.65), (25.9e-9, 1.2, 0),
               (28e-9, 1.2, 0), (28.2e-9, .6, 1.65), (28.4e-9, 0, 3.3)]
    rows = []
    for time, ref, sample in vectors:
        ref_drop, sample_drop = min(ref, .001), min(sample, .005)
        ref_port, sample_port = ref-ref_drop, sample-sample_drop
        rows.append([time, ref_port, ref_port-ref_drop*(28000/11)/50,
                     sample_port, sample_port-sample_drop*7000/50])
    assert source_profile(header, rows, 'nominal')['passed']
    for index in (1, 3):
        bad = [r[:] for r in rows]
        bad[2][index] -= .05
        assert not source_profile(header, bad, 'nominal')['passed']
    # A half-speed feedback edge has only reached 0.825 V at the same instant.
    bad = [r[:] for r in rows]
    bad[2][3] = bad[2][4] = .825
    assert not source_profile(header, bad, 'nominal')['passed']
    bad = [r[:] for r in rows]
    bad[-1][3] = bad[-1][4] = 0
    assert not source_profile(header, bad, 'nominal')['passed']
    try:
        source_profile(header, [], 'nominal')
    except ValueError:
        pass
    else:
        raise AssertionError('missing waveform accepted')
    print('PASS: finite source reconstruction, both input errors, slowed edge, missing pulse, empty trace')


if __name__ == '__main__':
    run()
